1	#!/usr/bin/env node
2	// Perform every declared migration's write side in a checkout:
3	//   - file aliases  — "prefer Y, fall back to X, and rename X -> Y"
4	//   - materialize   — vendor pack templates into the repo's own tree
5	//   - rewrite       — repoint refs in place (idempotent literal replacements)
6	//   - declarePacks  — declare a pack (and its config) the member does not carry yet
7	// Idempotent: a no-op once everything has been applied. Dependency-free.
8	//
9	// Two roots. The DEST is the repo being healed (CLAUDE_PROJECT_DIR / cwd). The
10	// TEMPLATE source is the canon that ships the migrations — the parent of this
11	// migrations/ dir: in the canon repo that's the repo root; in a consumer that
12	// mounts Claudinite at .claudinite/, it's .claudinite/ (so a template path like
13	// packs/…/stubs/foo.yml resolves against the mounted pack, while its dest lands
14	// in the consumer's own .github/). The two coincide in the canon repo.
15	//
16	// Runs against a local checkout (a session, CI, or a future SessionStart
17	// self-heal hook wired via bootstrap). Each member migrates ITSELF: baselining
18	// runs this applier from the fresh canon clone it fetched, so even a dormant
19	// project catches up on every record ever landed — there is no fleet-wide
20	// apply pass and no retirement; the records simply accumulate.
21	import { existsSync, renameSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
22	import { dirname, join } from 'node:path';
23	import { fileURLToPath, pathToFileURL } from 'node:url';
24	import { loadMigrations, applyFileAliases, applyMaterializations, applyRewrites, applyPackDeclarations } from './registry.mjs';
25	
26	async function main() {
27	  const repoRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
28	  const canonRoot = dirname(dirname(fileURLToPath(import.meta.url))); // parent of migrations/
29	  const migrations = await loadMigrations();
30	
31	  const exists = (p) => existsSync(join(repoRoot, p));
32	  const read = (p) => (existsSync(join(repoRoot, p)) ? readFileSync(join(repoRoot, p), 'utf8') : null);
33	  const write = (p, c) => {
34	    mkdirSync(dirname(join(repoRoot, p)), { recursive: true });
35	    writeFileSync(join(repoRoot, p), c);
36	  };
37	  const move = (from, to) => {
38	    mkdirSync(dirname(join(repoRoot, to)), { recursive: true });
39	    renameSync(join(repoRoot, from), join(repoRoot, to));
40	  };
41	  const readTemplate = (p) => (existsSync(join(canonRoot, p)) ? readFileSync(join(canonRoot, p), 'utf8') : null);
42	
43	  const applied = [];
44	  for (const m of migrations) {
45	    applied.push(...(await applyFileAliases(m, { exists, move })));
46	    applied.push(...(await applyMaterializations(m, { readTemplate, read, write })));
47	    applied.push(...(await applyRewrites(m, { read, write })));
48	    applied.push(...(await applyPackDeclarations(m, { read, write })));
49	  }
50	  if (applied.length) console.log(`Applied migrations:\n${applied.map((x) => `  ${x}`).join('\n')}`);
51	}
52	
53	const isMain = process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href;
54	if (isMain) {
55	  main().catch((e) => { console.error(`migrations apply failed: ${e.message}`); process.exit(1); });
56	}
57

1	import { readdirSync, existsSync } from 'node:fs';
2	import { join, dirname } from 'node:path';
3	import { fileURLToPath } from 'node:url';
4	
5	// The synchronous migration-registry surface for the CHECK layer. It lives in
6	// the engine lib — not migrations/ — because pack checks consult it
7	// (`migrationActive` gates an in-flight transition's legacy tolerance) and a
8	// pack imports only its own files and the engine surface (pack-independence):
9	// the canon-internal migrations/ tree is never vendored, so an import into it
10	// would crash every vendored consumer. Self-locating relative to the engine
11	// root, so in a vendored consumer — where migrations/ carries only the recent
12	// vendored records, or nothing — every query answers from what the mount
13	// actually holds. The full registry (migrations/registry.mjs) builds on this
14	// same surface canon-side.
15	//
16	// One flat home: every migration lives at migrations/<landed-date>-<slug>/,
17	// with its spec at migration.mjs. All records are equal — there is no
18	// active/archived split and no cleanup pass; FETCHING decides relevance.
19	// Vendoring ships only the records landed within RECENT_WINDOW_DAYS, so an
20	// up-to-date consumer carries few-to-none, while a dormant project baselining
21	// out of a fresh canon clone sees them all and applies what it needs.
22	export const MIGRATION_FILE = 'migration.mjs';
23	export const RECENT_WINDOW_DAYS = 7;
24	const migrationsRoot = join(dirname(dirname(dirname(dirname(fileURLToPath(import.meta.url))))), 'migrations'); // <canon>/engine/checks/helpers/
25	const isRecordDir = (name) => /^\d{4}-\d{2}-\d{2}-/.test(name);
26	
27	// Every migration record folder present, sorted (= chronological: the landed-date
28	// prefix is the folder-name convention). Tolerant of an absent/empty migrations
29	// root — a vendored consumer with no recent records.
30	export function migrationDirs() {
31	  try {
32	    return readdirSync(migrationsRoot, { withFileTypes: true })
33	      .filter((e) => e.isDirectory() && isRecordDir(e.name) && existsSync(join(migrationsRoot, e.name, MIGRATION_FILE)))
34	      .map((e) => e.name)
35	      .sort();
36	  } catch { return []; }
37	}
38	
39	const todayIso = () => new Date().toISOString().slice(0, 10);
40	
41	// True while a record folder's landed-date prefix is within the recency window —
42	// the same predicate vendoring uses to decide what ships in a consumer mount,
43	// so "recent enough to tolerate" and "recent enough to vendor" can never drift.
44	// Pure over the folder NAME, so vendoring can apply it against its own tree walk.
45	export function recordDirIsRecent(name, today = todayIso()) {
46	  const cutoff = new Date(`${today}T00:00:00Z`).getTime() - RECENT_WINDOW_DAYS * 86400000;
47	  const landedMs = new Date(`${name.slice(0, 10)}T00:00:00Z`).getTime();
48	  return Number.isFinite(landedMs) && landedMs > cutoff;
49	}
50	
51	// True while a migration whose folder name carries `slug` is present AND recent —
52	// a check consults it to know whether an in-flight transition's legacy shape is
53	// still tolerated. Recency bounds the tolerance on the canon (where every record
54	// stays forever) and in a stale mount alike: every up-to-date repo converges
55	// within the window, and a dormant one is converged by baselining's apply step
56	// BEFORE its checks run, so an aged record needs no tolerance anywhere.
57	export function migrationActive(slug, today = todayIso()) {
58	  return migrationDirs().some((d) => d.includes(slug) && recordDirIsRecent(d, today));
59	}
